<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class CurriculumController extends Controller{
 private function manage(Request $r,$teacherId=null){$u=$r->user();abort_unless($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('academic_head')||($u->teacher_id&&(!$teacherId||$u->teacher_id==$teacherId)),403);}
 public function index(Request $r){$p=$r->attributes->get('academic_period');$u=$r->user();$q=DB::table('curriculum_plans as cp')->join('study_groups as g','g.id','=','cp.study_group_id')->join('subjects as s','s.id','=','cp.subject_id')->leftJoin('teachers as t','t.id','=','cp.teacher_id')->where('cp.academic_period_id',$p->id)->select('cp.*','g.name as group_name','s.name as subject_name','t.last_name','t.first_name');if($u->teacher_id&&!($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('academic_head')))$q->where('cp.teacher_id',$u->teacher_id);$plans=$q->orderBy('g.name')->orderBy('s.name')->get();foreach($plans as $x){$x->planned=DB::table('curriculum_topics')->where('curriculum_plan_id',$x->id)->sum('planned_hours');$x->done=DB::table('lesson_occurrences')->whereNotNull('curriculum_topic_id')->whereIn('curriculum_topic_id',DB::table('curriculum_topics')->where('curriculum_plan_id',$x->id)->pluck('id'))->whereNotIn('status',['cancelled'])->where('lesson_date','<=',now()->toDateString())->count();}$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$subjects=DB::table('subjects')->orderBy('name')->get();$teachers=DB::table('teachers')->where('active',1)->orderBy('last_name')->get();return view('curriculum.index',compact('plans','groups','subjects','teachers'));}
 public function store(Request $r){$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['study_group_id'=>'required|exists:study_groups,id','subject_id'=>'required|exists:subjects,id','teacher_id'=>'nullable|exists:teachers,id','title'=>'nullable|string|max:255']);$teacher=$d['teacher_id']??$r->user()->teacher_id;$this->manage($r,$teacher);DB::table('curriculum_plans')->updateOrInsert(['academic_period_id'=>$p->id,'study_group_id'=>$d['study_group_id'],'subject_id'=>$d['subject_id'],'teacher_id'=>$teacher],['title'=>$d['title']??null,'status'=>'active','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Рабочая программа создана.');}
 public function show(Request $r,$plan){$cp=DB::table('curriculum_plans as cp')->join('study_groups as g','g.id','=','cp.study_group_id')->join('subjects as s','s.id','=','cp.subject_id')->leftJoin('teachers as t','t.id','=','cp.teacher_id')->where('cp.id',$plan)->select('cp.*','g.name as group_name','s.name as subject_name','t.last_name','t.first_name')->first();abort_if(!$cp,404);$this->manage($r,$cp->teacher_id);$topics=DB::table('curriculum_topics')->where('curriculum_plan_id',$plan)->orderBy('sort_order')->get();foreach($topics as $x){$x->lessons=DB::table('lesson_occurrences')->where('curriculum_topic_id',$x->id)->whereNotIn('status',['cancelled'])->count();}$planned=$topics->sum('planned_hours');$done=$topics->sum('lessons');return view('curriculum.show',compact('cp','topics','planned','done'));}
 public function topic(Request $r,$plan){$cp=DB::table('curriculum_plans')->find($plan);abort_if(!$cp,404);$this->manage($r,$cp->teacher_id);PeriodGuard::writable($cp->academic_period_id);$d=$r->validate(['section'=>'nullable|string|max:255','title'=>'required|string|max:2000','planned_hours'=>'required|numeric|min:0.1|max:999','planned_on'=>'nullable|date','control_type'=>'nullable|string|max:100','is_checkpoint'=>'nullable|boolean','note'=>'nullable|string|max:3000']);$d['is_checkpoint']=$r->boolean('is_checkpoint');$d['sort_order']=(DB::table('curriculum_topics')->where('curriculum_plan_id',$plan)->max('sort_order')??0)+1;DB::table('curriculum_topics')->insert(array_merge($d,['curriculum_plan_id'=>$plan,'created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Тема КТП добавлена.');}
 public function bind(Request $r,$lesson){$l=DB::table('lesson_occurrences')->find($lesson);abort_if(!$l,404);$this->manage($r,$l->teacher_id);PeriodGuard::writable($l->academic_period_id);$d=$r->validate(['curriculum_topic_id'=>'nullable|exists:curriculum_topics,id']);if($d['curriculum_topic_id']){abort_unless(DB::table('curriculum_topics as ct')->join('curriculum_plans as cp','cp.id','=','ct.curriculum_plan_id')->where('ct.id',$d['curriculum_topic_id'])->where(['cp.academic_period_id'=>$l->academic_period_id,'cp.study_group_id'=>$l->study_group_id,'cp.subject_id'=>$l->subject_id])->exists(),422);}DB::table('lesson_occurrences')->where('id',$lesson)->update(['curriculum_topic_id'=>$d['curriculum_topic_id']?:null,'updated_at'=>now()]);return back()->with('success','Занятие связано с КТП.');}
}